You can turn a bubble into a link or button by using the `render` prop on `BubbleContent`.

```tsx
import { Bubble, BubbleContent } from "@erbium/ui/components/bubble";

export function BubbleLinkDemo() {
  return (
    <Bubble variant="muted">
      <BubbleContent render={<button />}>Click here</BubbleContent>
    </Bubble>
  );
}
```

Use a state and the `setApi` prop to get an instance of the carousel API.

```tsx
import { type CarouselApi } from "@erbium/ui/components/carousel";

export function Example() {
  const [api, setApi] = React.useState<CarouselApi>();
  const [current, setCurrent] = React.useState(0);
  const [count, setCount] = React.useState(0);

  React.useEffect(() => {
    if (!api) {
      return;
    }

    setCount(api.scrollSnapList().length);
    setCurrent(api.selectedScrollSnap() + 1);

    api.on("select", () => {
      setCurrent(api.selectedScrollSnap() + 1);
    });
  }, [api]);

  return (
    <Carousel setApi={setApi}>
      <CarouselContent>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
      </CarouselContent>
    </Carousel>
  );
}
```

You can listen to events using the api instance from `setApi`.

See the [Embla Carousel docs](https://www.embla-carousel.com/api/events/) for more information on using events.

```tsx
import { type CarouselApi } from "@erbium/ui/components/carousel";

export function Example() {
  const [api, setApi] = React.useState<CarouselApi>();

  React.useEffect(() => {
    if (!api) {
      return;
    }

    api.on("select", () => {
      // Do something on select.
    });
  }, [api]);

  return (
    <Carousel setApi={setApi}>
      <CarouselContent>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
      </CarouselContent>
    </Carousel>
  );
}
```

You can use the `plugins` prop to add plugins to the carousel.

```ts
import Autoplay from "embla-carousel-autoplay"

export function Example() {
  return (
    <Carousel
      plugins={[
        Autoplay({
          delay: 2000,
        }),
      ]}
    >
      // ...
    </Carousel>
  )
}
```

TanStack Charts renders the legend from the chart definition. The example maps Desktop and Mobile to fixed colors and enables a legend labeled Device.

```tsx
import { colorLegend, colorLegendItems } from "@tanstack/charts/legend";
import { scaleOrdinal } from "@tanstack/charts/scales/ordinal";

const definition = defineChart({
  marks,
  scales,
  color: {
    scale: scaleOrdinal(["Desktop", "Mobile"], ["var(--chart-1)", "var(--chart-2)"]),
    legend: colorLegend({
      label: "Device",
      items: colorLegendItems({
        justify: "start",
        gap: 16,
        rowGap: 8,
        indicator: { shape: "dot", width: 8, height: 8, gap: 7 },
        label: { fontSize: 13, fontWeight: 500, fill: "var(--muted-foreground)" },
      }),
    }),
  },
});
```

Hover or focus a bar to inspect its value. The chart definition enables grouped focus and TanStack Charts' tooltip extension. The shared month appears as the heading, with a value and color swatch for each device.

```tsx
import { tooltip } from "@tanstack/charts/tooltip";

const definition = defineChart({
  marks,
  scales,
  focus: "group-x",
  tooltip: { use: tooltip, className: "erbium-chart-tooltip" },
});
```

Configure tooltip content with `items`, `format`, or `formatGroup` in the definition. See the [TanStack Charts tooltip guide](https://tanstack.com/charts/latest/docs/framework/react/guides/tooltips-and-focus) for placement and formatting options.

Use the `open` and `onOpenChange` props to control the state.

```tsx
import * as React from "react";

export function Example() {
  const [open, setOpen] = React.useState(false);

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <CollapsibleTrigger>Toggle</CollapsibleTrigger>
      <CollapsibleContent>Content</CollapsibleContent>
    </Collapsible>
  );
}
```

Use `itemToStringValue` when your items are objects.

```tsx
import * as React from "react";

import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
} from "@erbium/ui/components/combobox";

type Framework = {
  label: string;
  value: string;
};

const frameworks: Framework[] = [
  { label: "TanStack Start", value: "tanstack-start" },
  { label: "SvelteKit", value: "sveltekit" },
  { label: "Nuxt", value: "nuxt" },
];

export function ExampleComboboxCustomItems() {
  return (
    <Combobox items={frameworks} itemToStringValue={(framework) => framework.label}>
      <ComboboxInput placeholder="Select a framework" />
      <ComboboxContent>
        <ComboboxEmpty>No items found.</ComboboxEmpty>
        <ComboboxList>
          {(framework) => (
            <ComboboxItem key={framework.value} value={framework}>
              {framework.label}
            </ComboboxItem>
          )}
        </ComboboxList>
      </ComboboxContent>
    </Combobox>
  );
}
```

You can render a custom component inside `ComboboxItem`.

Use `multiple` with chips for multi-select behavior.

```tsx
import * as React from "react";

import {
  Combobox,
  ComboboxChip,
  ComboboxChips,
  ComboboxChipsInput,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
  ComboboxValue,
} from "@erbium/ui/components/combobox";

const frameworks = ["TanStack Start", "SvelteKit", "Nuxt.js", "Remix", "Astro"];

export function ExampleComboboxMultiple() {
  const [value, setValue] = React.useState<string[]>([]);

  return (
    <Combobox items={frameworks} multiple value={value} onValueChange={setValue}>
      <ComboboxChips>
        <ComboboxValue>
          {value.map((item) => (
            <ComboboxChip key={item}>{item}</ComboboxChip>
          ))}
        </ComboboxValue>
        <ComboboxChipsInput placeholder="Add framework" />
      </ComboboxChips>
      <ComboboxContent>
        <ComboboxEmpty>No items found.</ComboboxEmpty>
        <ComboboxList>
          {(item) => (
            <ComboboxItem key={item} value={item}>
              {item}
            </ComboboxItem>
          )}
        </ComboboxList>
      </ComboboxContent>
    </Combobox>
  );
}
```

A combobox with multiple selection using `multiple` and `ComboboxChips`.

Turn a marker into a link or button with the `render` prop on `Marker`.

```tsx
import { Marker, MarkerContent } from "@erbium/ui/components/marker";

export function MarkerLinkDemo() {
  return (
    <Marker render={<a href="#" />}>
      <MarkerContent>View the pull request</MarkerContent>
    </Marker>
  );
}
```

Use the `render` prop to compose a custom link component such as TanStack Router `Link`.

```tsx
import { Link } from "@tanstack/react-router";

import {
  NavigationMenuItem,
  NavigationMenuLink,
  navigationMenuTriggerStyle,
} from "@erbium/ui/components/navigation-menu";

export function NavigationMenuDemo() {
  return (
    <NavigationMenuItem>
      <NavigationMenuLink render={<Link to="/docs" />} className={navigationMenuTriggerStyle()}>
        Documentation
      </NavigationMenuLink>
    </NavigationMenuItem>
  );
}
```

Use the `open` and `onOpenChange` props to control the sidebar.

```tsx
export function AppSidebar() {
  const [open, setOpen] = React.useState(false);

  return (
    <SidebarProvider open={open} onOpenChange={setOpen}>
      <Sidebar />
    </SidebarProvider>
  );
}
```

Pass button props with `actionProps` to render an action. This example closes the toast; a real Undo handler must also restore application state.

```tsx
const id = toast.add({
  id: "event-created",
  title: "Event created",
  actionProps: {
    children: "Undo",
    onClick() {
      toast.close(id);
    },
  },
});
```
